pub const STANDARD: Self = Self::new(
    UI_BINDING_VALUE_MAX_DEPTH,
    UI_BINDING_VALUE_MAX_NODES,
    UI_BINDING_VALUE_MAX_STRING_BYTES,
    UI_BINDING_VALUE_MAX_COLLECTION_ENTRIES,
);

assertions.exact_expression:
assert!(
    single_buffer_samples[p95].saturating_mul(2) <= allocating_samples[p95],
    "single-buffer native binding projection must improve P95 by at least 50%: allocating={}ns single_buffer={}ns",
    allocating_samples[p95],
    single_buffer_samples[p95],
);

assert!(
    streaming_samples[p95].saturating_mul(2) <= allocating_samples[p95],
    "streamed binding map entry projection must improve P95 by at least 50%: allocating={}ns streaming={}ns",
    allocating_samples[p95],
    streaming_samples[p95],
);

assert_eq!(
    UiBindingValue::Array(vec![
        UiBindingValue::Unsigned(4),
        UiBindingValue::Bool(true)
    ])
    .to_json_value(),
    serde_json::json!([4, true])
);

assert!(
    reduction_percent >= 95,
    "controlled collection view must reduce the serialized payload by at least 95%"
);

